from collections import deque
from decimal import Decimal

class ExpressionCalculator:
    """
    This is a class in Python that can perform calculations with basic arithmetic operations, including addition, subtraction, multiplication, division, and modulo.
    """

    def __init__(self):
        """
        Initialize the expression calculator
        """
        self.postfix_stack = deque()
        # Priority mapping for operators: {'+', '-', '*', '/', '(', ')', '%'}
        # Based on the provided list [0, 3, 2, 1, -1, 1, 0, 2], we map them to a dict for clarity
        self.priority_map = {'+': 1, '-': 1, '*': 2, '/': 2, '%': 2, '(': 0, ')': 0}

    def calculate(self, expression):
        """
        Calculate the result of the given postfix expression
        :param expression: string, the infix expression to be calculated
        :return: float, the calculated result
        """
        self.prepare(expression)
        stack = []

        # Process the postfix notation stored in self.postfix_stack
        while self.postfix_stack:
            token = self.postfix_stack.popleft()
            if not self.is_operator(token) or token in '()':
                stack.append(token)
            else:
                val2 = stack.pop()
                val1 = stack.pop()
                result = self._calculate(val1, val2, token)
                stack.append(str(result))

        return float(stack[0])

    def prepare(self, expression):
        """
        Prepare the infix expression for conversion to postfix notation
        :param expression: string, the infix expression to be prepared
        """
        infix = self.transform(expression)
        self.postfix_stack = deque()
        op_stack = []

        i = 0
        while i < len(infix):
            char = infix[i]
            if char.isdigit() or char == '.':
                num = ""
                while i < len(infix) and (infix[i].isdigit() or infix[i] == '.'):
                    num += infix[i]
                    i += 1
                self.postfix_stack.append(num)
                continue
            elif char == '(':
                op_stack.append(char)
            elif char == ')':
                while op_stack and op_stack[-1] != '(':
                    self.postfix_stack.append(op_stack.pop())
                if op_stack:
                    op_stack.pop()
            elif self.is_operator(char):
                while op_stack and op_stack[-1] != '(' and self.compare(op_stack[-1], char):
                    self.postfix_stack.append(op_stack.pop())
                op_stack.append(char)
            i += 1

        while op_stack:
            self.postfix_stack.append(op_stack.pop())

    @staticmethod
    def is_operator(c):
        """
        Check if a character is an operator in {'+', '-', '*', '/', '(', ')', '%'}
        :param c: string, the character to be checked
        :return: bool, True if the character is an operator, False otherwise
        """
        return c in {'+', '-', '*', '/', '(', ')', '%'}

    def compare(self, peek, cur):
        """
        Compare the precedence of two operators
        :param peek: string, the operator at the top of the operator stack
        :param cur: string, the current operator
        :return: bool, True if the peek operator has higher or equal precedence, False otherwise
        """
        return self.priority_map.get(peek, 0) >= self.priority_map.get(cur, 0)

    @staticmethod
    def _calculate(first_value, second_value, current_op):
        """
        Perform the mathematical calculation based on the given operands and operator
        :param first_value: string, the first operand
        :param second_value: string, the second operand
        :param current_op: string, the operator
        :return: float, the calculated result
        """
        v1 = Decimal(first_value)
        v2 = Decimal(second_value)

        if current_op == '+':
            res = v1 + v2
        elif current_op == '-':
            res = v1 - v2
        elif current_op == '*':
            res = v1 * v2
        elif current_op == '/':
            res = v1 / v2
        elif current_op == '%':
            res = v1 % v2
        else:
            res = Decimal(0)

        return float(res)

    @staticmethod
    def transform(expression):
        """
        Transform the infix expression to a format suitable for conversion
        :param expression: string, the infix expression to be transformed
        :return: string, the transformed expression
        """
        return expression.replace(" ", "")
